import {topicContent,topicId} from './course-content.js';
import {ageQuestions} from './course-ages.js';
import {canOpenTopic,recordFor,answerQuestion,nextQuestion} from './learning.js';
import {modelSpec,modelVisual,computeModel} from './course-models.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createCourseUI({getState,getSubject,getIndex,save,render,notify,runCode}){let value=null,current='',frame=0,playing=null,feedback='',hinted=false,selected=null;
 function context(){const state=getState(),subject=getSubject(),index=getIndex(),t=topicContent(subject,index,state.age),r=recordFor(state,subject,index);const key=topicId(state.age,subject,index);if(current!==key){stop();current=key;value=modelSpec(t.model).initial;frame=0;feedback='';hinted=false;selected=null}return {state,subject,index,t,r};}
 function stop(){if(playing)clearInterval(playing);playing=null}
 function controls(t){const s=modelSpec(t.model);return `<div class="controls"><label for="course-variable">${e(s.label)} <input id="course-variable" type="range" min="${s.min}" max="${s.max}" step="1" value="${value}"><output>${value}</output></label><button class="btn secondary small" data-course="step">Next model state →</button><button class="btn secondary small" data-course="play">${playing?'Pause':'Play demonstration'}</button></div>`}
 function practice(t,r){const qs=ageQuestions(t),i=selected??nextQuestion(r),q=qs[i],young=t.age==='primary';return `<div class="practice-route"><span class="pill blue">${r.correct.length}/3 skills demonstrated</span><span class="pill">${['Guided practice','Independent practice','Extension'][r.level]}</span></div><div class="question-tabs">${qs.map((q,j)=>`<button data-question="${j}" ${j>0&&!r.correct.includes(0)?'disabled':''} class="${j===i?'active':''}">${r.correct.includes(j)?'✓ ':''}${young?'Try '+(j+1):['Guided check','Apply independently','Extend your reasoning'][j]}</button>`).join('')}</div><form id="course-answer" data-question="${i}"><p class="question">${e(q.prompt)}</p>${young?`<div class="choice-grid">${(/Enter 1/i.test(q.prompt)?[0,1]:[q.answer-1,q.answer,q.answer+1]).sort((a,b)=>a-b).map(n=>`<button type="button" data-choice="${n}" class="btn secondary">${/Enter 1/i.test(q.prompt)?(n?'Yes':'No'):n}</button>`).join('')}</div><label class="micro">Or enter your answer</label>`:'<label>Your calculated answer</label>'}<div class="stack"><input id="course-numeric" type="number" step="any" required class="answer-input" aria-label="Answer"><button class="btn" type="submit">Check understanding</button></div>${!young?'<label class="reason-label">Your reasoning (saved as notes)</label><textarea id="course-reasoning" class="notes" placeholder="Show the steps, assumptions, and units.">'+e(getState().notes[topicId(t.age,t.subject,t.index,'reason-'+i)]||'')+'</textarea>':''}</form><button class="link" data-course="hint">${young?'Help me think':'Show a worked hint'}</button><div id="course-feedback" aria-live="polite">${feedback}</div>${r.correct.length===3?`<div class="feedback"><b>✓ Topic mastered</b><p>Your two lesson completions are saved. ${t.index<5?'The next topic is unlocked.':'You have reached the end of this subject path.'}</p></div>`:''}`;}
 function project(t,r){const p=r.project;return `<section class="course-project"><span class="eyebrow">${t.age==='primary'?'MAKE AND TELL':'PROJECT NOTEBOOK'}</span><h3>${e(t.project)}</h3><p>${e(t.rubric)}</p>${[['prediction','My plan or prediction'],['evidence','What I measured or observed'],['conclusion','What I learned and would improve']].map(([k,label])=>`<label>${label}<textarea class="notes" data-project-field="${k}" placeholder="${label}">${e(p[k]||'')}</textarea></label>`).join('')}<button class="btn secondary" data-course="project">Save project reflection</button><p class="micro">This is a saved self-assessment, not an automated grade. Check your explanation against the rubric.</p></section>`;}
 function view(){const {state,subject,index,t,r}=context();if(!canOpenTopic(state,subject,index))return `<button class="link" data-action="overview">← Subject path</button><section class="panel"><span class="pill">Locked</span><h1>${e(t.title)}</h1><p>Complete the three understanding checks in topic ${index} to unlock this topic. You can review earlier lessons anytime.</p><button class="btn" data-topic="${index-1}">Open prerequisite topic →</button></section>`;const young=state.age==='primary',middle=state.age==='middle',advanced=state.age==='advanced';const mode=young?'Story → Try → Show':middle?'Discover → Experiment → Explain':advanced?'Theory → Investigation → Evaluation':'Understand → Build → Solve';return `<button class="link" data-action="overview">← ${e(subject)} learning path</button><article class="course-workspace course-${state.age}"><header><span class="eyebrow">TOPIC ${index+1} / ${mode}</span><h1>${e(t.title)}</h1><p class="muted">${young?t.story:t.why}</p><div class="audio"><button data-course="speak">Read aloud</button><button data-course="pause-audio">Pause / resume</button><button data-course="stop-audio">Stop</button><label>Speed <select id="course-rate"><option value="0.8">0.8×</option><option value="1" selected>1×</option><option value="1.2">1.2×</option></select></label></div></header><nav class="course-steps" aria-label="Topic stages">${['Understand','Explore','Practice & project'].map((x,i)=>`<button data-course-stage="${i}" ${i>r.stage?'disabled':''} class="${r.stage===i?'active':''}">${i+1}. ${young?['Watch','Try','Show'][i]:x}</button>`).join('')}</nav><div class="course-columns"><div class="course-main">${r.stage===0?`${young?'':`<section class="step-card"><h3>Before you begin</h3><p>${e(t.prereq)}</p><h3>The central idea</h3><p>${e(t.concept)}</p><p>${e(t.depth)}</p>${advanced?`<h3>Theoretical extension</h3><p>${e(t.advanced)}</p>`:''}</section>`}${modelVisual(t.model,value,state.age,!!playing)}${controls(t)}${young?`<p class="story-line">${e(t.story.split('. ').filter(Boolean)[frame%t.story.split('. ').filter(Boolean).length])}</p>`:`<section class="worked-examples"><h3>Worked examples</h3>${t.worked.map((x,i)=>`<div class="step-card"><span class="step-number">${i+1}</span><p>${e(x)}</p></div>`).join('')}</section>`}<button class="btn" data-course="advance">${young?'Let me try →':'Open the investigation →'}</button>`:r.stage===1?`<section class="step-card"><h3>${middle?'Make a prediction':young?'Try changing one thing':'Investigation brief'}</h3><p>${young?t.story:t.project}</p>${modelVisual(t.model,value,state.age,!!playing)}${controls(t)}${middle?`<div class="mission-prediction"><label>Predict the model’s numeric result for the current input <input id="model-prediction" type="number" step="any" class="answer-input"></label><button class="btn secondary small" data-course="predict">Compare with the experiment</button><p id="prediction-feedback" aria-live="polite"></p></div>`:''}${advanced?`<details><summary>Parameter sweep and research data</summary><p>Compare all integer inputs in the displayed model range. These are computed model outputs, not physical measurements.</p><table class="table"><thead><tr><th>Input</th><th>Output</th></tr></thead><tbody>${Array.from({length:modelSpec(t.model).max-modelSpec(t.model).min+1},(_,i)=>{const x=modelSpec(t.model).min+i;return `<tr><td>${x}</td><td>${computeModel(t.model,x).result}</td></tr>`}).join('')}</tbody></table><button class="btn secondary small" data-course="csv">Download computed data (CSV)</button></details>`:''}<h3>${young?'Notice this':'Check the limits of the model'}</h3><p>${e(t.mistake)}</p>${advanced?`<details><summary>Research notes and assumptions</summary><p>${e(t.advanced)}</p></details>`:''}</section>${subject==='coding'&&!young?`<h3>JavaScript investigation</h3><p class="micro">Edit and test this example in the bounded worker. Output is computed locally.</p><textarea class="code-editor" id="code" aria-label="JavaScript editor" spellcheck="false">${e(codeFor(index))}</textarea><button class="btn small" data-action="run">Run code ▷</button><pre class="output" id="code-output">Output appears here.</pre>`:''}<button class="btn" data-course="advance">${young?'Show what I know →':'Start guided practice →'}</button>`:`<section class="panel">${practice(t,r)}</section>${project(t,r)}`}</div>${young?'':`<aside class="course-aside"><h3>${advanced?'Research log':'Learning notebook'}</h3><p>${e(t.prereq)}</p><div class="mini-item"><div><b>Lesson 1 · Understand</b><p>${state.completed[topicId(state.age,subject,index,'learn')]?'✓ Demonstrated':'Complete the guided check'}</p></div></div><div class="mini-item"><div><b>Lesson 2 · Apply</b><p>${state.completed[topicId(state.age,subject,index,'apply')]?'✓ Mastered':'Complete all three checks'}</p></div></div><p>${e(t.rubric)}</p><p class="micro">Difficulty recommendations use your attempts and hint use. Age changes the explanation and interaction, not a fixed ability judgment.</p></aside>`}</div></article>`;}
 function codeFor(i){return ['const values = [3, 8, 5];\nlet best = values[0];\nfor (const value of values) {\n  if (value > best) best = value;\n}\nconsole.log(best);','let score = 4;\nscore = score + 3;\nconsole.log(score);\nconsole.log("4" + 3);','const age = 10;\nif (age < 10) {\n  console.log("child ticket");\n} else {\n  console.log("other ticket");\n}','let total = 0;\nfor (let i = 1; i <= 4; i++) {\n  total += i;\n}\nconsole.log(total);','function area(width, height) {\n  return width * height;\n}\nconsole.log(area(3, 4));\nconsole.log(area(0, 5));','const values = [4, 7, 9];\nconsole.log(values.indexOf(7));\nconsole.log(values.indexOf(3));'][i];}
 function step(){const {t}=context(),s=modelSpec(t.model);frame=(frame+1)%4;const count=Math.min(4,s.max-s.min+1),states=Array.from({length:count},(_,i)=>s.min+Math.round(i*(s.max-s.min)/(count-1)));value=states.find(x=>x>value)??states[0];render();}
 document.addEventListener('click',evt=>{const b=evt.target.closest('button');if(!b||!document.querySelector('.course-workspace'))return;const {state,subject,index,t,r}=context();if(b.dataset.courseStage!==undefined){const n=Number(b.dataset.courseStage);if(n<=r.stage){r.stage=n;stop();save();render()}return}if(b.dataset.question!==undefined){selected=Number(b.dataset.question);hinted=false;feedback='';render();return}if(b.dataset.choice!==undefined){document.querySelector('#course-numeric').value=b.dataset.choice;document.querySelector('#course-answer').requestSubmit();return}const a=b.dataset.course;if(!a)return;if(a==='predict'){const input=document.querySelector('#model-prediction');if(input.value===''){notify('Make a prediction first.');return}const actual=computeModel(t.model,value).result;document.querySelector('#prediction-feedback').textContent='Your prediction: '+input.value+'. Model output: '+actual+'. '+(Math.abs(Number(input.value)-actual)<.011?'Your prediction matches. Explain why.':'Compare the rule with your prediction, then change one variable and retry.');}if(a==='csv'){const s=modelSpec(t.model),lines=['input,output'];for(let x=s.min;x<=s.max;x++)lines.push(x+','+computeModel(t.model,x).result);const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=t.subject+'-topic-'+(t.index+1)+'-model.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}if(a==='advance'){r.stage=Math.min(2,r.stage+1);stop();save();render()}if(a==='step')step();if(a==='play'){if(state.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches){step();return}if(playing)stop();else playing=setInterval(step,2200);render()}if(a==='hint'){hinted=true;const i=selected??nextQuestion(r);feedback=`<div class="feedback">${e(ageQuestions(t)[i].reason)}</div>`;render()}if(a==='project'){if(['prediction','evidence','conclusion'].some(k=>!r.project[k]?.trim())){notify('Add a plan, evidence, and conclusion before saving your reflection.');return}r.project.savedAt=new Date().toISOString();save();notify('Project reflection saved. Review it against the rubric.')}if(a==='speak'){if(!('speechSynthesis'in window)){notify('Read aloud is unavailable; the explanation remains on screen.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(document.querySelector('.course-main').innerText);u.rate=Number(document.querySelector('#course-rate').value);u.onerror=()=>notify('Audio is unavailable. Use the written explanation.');speechSynthesis.speak(u)}if(a==='pause-audio'&&'speechSynthesis'in window){speechSynthesis.paused?speechSynthesis.resume():speechSynthesis.pause()}if(a==='stop-audio')window.speechSynthesis?.cancel()});
 document.addEventListener('input',evt=>{if(!document.querySelector('.course-workspace'))return;const {state,t,r}=context();if(evt.target.id==='course-variable'){value=Number(evt.target.value);document.querySelector('.course-model').outerHTML=modelVisual(t.model,value,state.age);evt.target.nextElementSibling.textContent=value}if(evt.target.dataset.projectField){r.project[evt.target.dataset.projectField]=evt.target.value;save()}if(evt.target.id==='course-reasoning'){const i=selected??nextQuestion(r);state.notes[topicId(t.age,t.subject,t.index,'reason-'+i)]=evt.target.value;save()}});
 document.addEventListener('submit',evt=>{if(evt.target.id!=='course-answer')return;evt.preventDefault();const {state,subject,index}=context();try{const a=answerQuestion(state,subject,index,Number(evt.target.dataset.question),Number(document.querySelector('#course-numeric').value),hinted);feedback=`<div class="feedback"><b>${a.ok?'✓ Correct reasoning target':'Let’s examine that result'}</b><p>${e(a.ok?a.reason:a.recommendation)}</p>${a.awarded?'<p>Topic complete. Your progress is saved.</p>':''}</div>`;save();render()}catch(err){notify(err.message)}});
 return {view,stop,context:()=>{const {t}=context();return t}};
}
